-- Users
create table if not exists public.profiles (
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  name text not null default '',
  email text not null default '',
  created_at text not null default '',
  last_active_at text not null default '',
  stage text not null default '',
  current_focus text not null default '',
  what_brought_you text not null default '',
  hoped_change text not null default '',
  is18_or_older text not null default '',
  plain_style text not null default '',
  prefs text not null default '',
  seq bigint generated always as identity,
  inserted_at timestamptz not null default now(),
  primary key (user_id)
);
alter table public.profiles add column if not exists name text not null default '';
alter table public.profiles add column if not exists email text not null default '';
alter table public.profiles add column if not exists created_at text not null default '';
alter table public.profiles add column if not exists last_active_at text not null default '';
alter table public.profiles add column if not exists stage text not null default '';
