alter table public.profiles add column if not exists what_brought_you text not null default '';
alter table public.profiles add column if not exists hoped_change text not null default '';
alter table public.profiles add column if not exists is18_or_older text not null default '';
alter table public.profiles add column if not exists plain_style text not null default '';
alter table public.profiles add column if not exists prefs text not null default '';
create index if not exists profiles_user_seq on public.profiles (user_id, seq);
alter table public.profiles enable row level security;
drop policy if exists own_rows on public.profiles;
create policy own_rows on public.profiles for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
revoke all on public.profiles from anon, authenticated;
grant select, insert, update on public.profiles to authenticated;

