-- Invite list. Only emails listed here can create an account during the alpha.
-- Add someone: insert into public.invites (email) values ('person@example.com');
create table if not exists public.invites (
  email text primary key,
  note text not null default '',
  invited_at timestamptz not null default now()
);
alter table public.invites enable row level security;
revoke all on public.invites from anon, authenticated;

create or replace function public.enforce_invite() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.invites i where lower(i.email) = lower(new.email)) then
    raise exception 'Life in Design is invite-only during the alpha.';
  end if;
  return new;
end;
$$;
revoke all on function public.enforce_invite() from public, anon, authenticated;
drop trigger if exists enforce_invite on auth.users;
create trigger enforce_invite before insert on auth.users for each row execute function public.enforce_invite();

-- Everything one person's request needs, in one call. Runs as the caller, so the own-rows rules apply.
create or replace function public.my_snapshot(ctx text default '') returns jsonb
language sql stable security invoker set search_path = '' as $$
  select jsonb_build_object(
    'profiles', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.profiles t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'design_record', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.design_record t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'element_history', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.element_history t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'belief_exploration', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.belief_exploration t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'chosen_beliefs', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.chosen_beliefs t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'parked_problems', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.parked_problems t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'commitments', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.commitments t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'sessions', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.sessions t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'messages', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.messages t where t.user_id = (select auth.uid()) and t.context = ctx), '[]'::jsonb),
    'assessments', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.assessments t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'journal_entries', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.journal_entries t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'growth_items', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.growth_items t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'recommendations', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.recommendations t where t.user_id = (select auth.uid())), '[]'::jsonb),
    'reviews', coalesce((select jsonb_agg(to_jsonb(t) - 'seq' - 'inserted_at' order by t.seq) from public.reviews t where t.user_id = (select auth.uid())), '[]'::jsonb)
  );
$$;
revoke all on function public.my_snapshot(text) from public, anon;
grant execute on function public.my_snapshot(text) to authenticated;
